import 'dart:io';
import 'package:surge_wizard/core/encounter_loader_v4.dart';import 'package:surge_wizard/core/headless_runner_v4.dart';
Future<void> main(List<String> args) async{final runs=args.isEmpty?5000:int.parse(args.first);final source=await File('assets/data/v4_vertical_slice_encounters.json').readAsString();final encounters=const EncounterLoaderV4().decode(source);const runner=HeadlessRunnerV4();stdout.writeln('encounter,runs,win_rate,avg_activations,avg_party_hp,avg_wizard_mp,avg_ko,avg_surge,avg_unstable');for(final encounter in encounters){var wins=0,activations=0,mp=0,ko=0,surge=0,unstable=0;var hp=0.0;for(var i=0;i<runs;i++){final r=runner.run(encounter:encounter,seed:23092026+i);if(r.won)wins++;activations+=r.activations;hp+=r.partyHpRatio;mp+=r.wizardMpRemaining;ko+=r.partyKo;surge+=r.surgeCount;unstable+=r.unstableCount;}stdout.writeln([encounter.id,runs,(wins/runs).toStringAsFixed(4),(activations/runs).toStringAsFixed(2),(hp/runs).toStringAsFixed(4),(mp/runs).toStringAsFixed(2),(ko/runs).toStringAsFixed(3),(surge/runs).toStringAsFixed(3),(unstable/runs).toStringAsFixed(3)].join(','));}}
